/**
 * Sayings funnel content (server only). Data is generated by
 * scripts/funnels/sayings/build_*.py into src/content/funnels/sayings/.
 */

import viv from '@/content/funnels/sayings/vivekananda.json'
import kab from '@/content/funnels/sayings/kabir.json'
import chk from '@/content/funnels/sayings/chanakya.json'
import type { DrawerData, L10n, Locale, Verdict, VivSource } from './shared'
import { chipText } from './shared'

export * from './shared'

// ── Vivekananda ─────────────────────────────────────────────────────────────

export type VivTheme = 'students' | 'education' | 'fear-and-strength' | 'work-and-success'
export const VIV_THEMES: VivTheme[] = ['students', 'education', 'fear-and-strength', 'work-and-success']

export type VivLine = {
  id: string
  slug: string
  text: string
  themes: VivTheme[]
  source: VivSource
  paragraph: string
  meaning: { hi: string; en?: string }
  card: boolean
  verdict: Verdict
  reviewed: boolean
}

export type VivCheck = {
  slug: string
  shared: string
  seenOn: string
  verdict: Verdict
  score: number
  real?: { text: string; source: VivSource; paragraph: string }
  also?: { text: string; source: VivSource }[]
  hubLine?: string
  note?: L10n
  reviewed: boolean
}

export type VivBridge = {
  chapter: number
  verse: number
  sanskritLine: string
  his: string
  source: VivSource
  note: L10n
}

type VivData = { edition: string; lines: VivLine[]; factChecks: VivCheck[]; gitaBridge: VivBridge[] }
const V = viv as unknown as VivData

export const vivLines = (): VivLine[] => V.lines
export const vivEdition = (): string => V.edition
export const vivLine = (slug: string): VivLine | null => V.lines.find((l) => l.slug === slug) ?? null
export const vivByTheme = (t: VivTheme): VivLine[] => V.lines.filter((l) => l.themes.includes(t))
export const vivChecks = (): VivCheck[] => V.factChecks
export const vivCheck = (slug: string): VivCheck | null => V.factChecks.find((c) => c.slug === slug) ?? null
export const vivBridge = (): VivBridge[] => V.gitaBridge

export function vivDrawer(line: VivLine, locale: Locale): DrawerData {
  return {
    quoteId: line.id,
    verdict: line.verdict,
    line: line.text,
    paragraph: line.paragraph,
    volume: line.source.volume,
    work: line.source.work,
    kind: line.source.kind[locale],
    url: line.source.url,
    translated: line.source.translatedFromBengali,
  }
}

export function checkDrawer(c: VivCheck, locale: Locale): DrawerData | null {
  if (!c.real) return null
  return {
    quoteId: `viv-check-${c.slug}`.slice(0, 60),
    verdict: c.verdict,
    line: c.real.text,
    paragraph: c.real.paragraph,
    volume: c.real.source.volume,
    work: c.real.source.work,
    kind: c.real.source.kind[locale],
    url: c.real.source.url,
    translated: c.real.source.translatedFromBengali,
  }
}

export { chipText }

// ── Kabir ───────────────────────────────────────────────────────────────────

export type KabirTheme = 'guru' | 'vani' | 'samay' | 'prem' | 'sach'
export type FoundIn = 'granthavali' | 'kavita-kaumudi' | 'sung'
export type Doha = {
  id: string
  slug: string
  theme: KabirTheme
  lines: string[]
  roman: string[]
  foundIn: FoundIn[]
  record: { id: string; section: string; url: string; quality: string }
  fixes: { from: string; to: string }[]
  meaning: L10n
  gloss: { w: string; hi: string; en: string }[]
  reviewed: boolean
}
type KabData = {
  sources: Record<FoundIn, L10n>
  dohe: Doha[]
  womenReview: { id: string; text: string; decision: 'keep' | 'exclude'; reason: string }[]
  notes: { misfiled: { id: string; text: string; reason: string }[]; missingFamous: string[]; nearDuplicates: number }
}
const K = kab as unknown as KabData

export const KABIR_THEMES: KabirTheme[] = ['guru', 'vani', 'samay', 'prem', 'sach']
export const dohe = (): Doha[] => K.dohe
export const doha = (slug: string): Doha | null => K.dohe.find((d) => d.slug === slug) ?? null
export const kabirSources = (): Record<FoundIn, L10n> => K.sources
export const kabirWomenReview = () => K.womenReview
export const kabirNotes = () => K.notes

// ── Chanakya ────────────────────────────────────────────────────────────────

export type ChkSection = 'log' | 'kaam' | 'dhan' | 'vidya' | 'man'
export type ChkVerse = {
  id: string
  ref: string
  chapter: number
  verse: number
  section: ChkSection
  lines: string[]
  roman: string[]
  meaning: { hi: string; en?: string }
  card: boolean
  reviewed: boolean
}
export type ChkSituation = { id: string; hi: string; en: string; refs: string[] }
export type ChkNotSaid = {
  slug: string
  line: L10n
  finding: L10n
  source?: { label: string; url: string }
  realRef?: string
}
type ChkData = {
  edition: string
  verses: ChkVerse[]
  situations: ChkSituation[]
  notSaid: ChkNotSaid[]
  womenReview: { mentions: number; excluded: number; items: { ref: string; decision: string; reason?: string }[] }
}
const CH = chk as unknown as ChkData

export const CHK_SECTIONS: ChkSection[] = ['log', 'kaam', 'dhan', 'vidya', 'man']
export const chkVerses = (): ChkVerse[] => CH.verses
export const chkVerse = (ref: string): ChkVerse | null => CH.verses.find((v) => v.ref === ref) ?? null
export const chkSituations = (): ChkSituation[] => CH.situations
export const chkNotSaid = (): ChkNotSaid[] => CH.notSaid
export const chkWomen = () => CH.womenReview
export const chkEdition = (): string => CH.edition
